def transform(grid):
    g = np.array(grid, copy=True)
    h, w = g.shape

    vals, counts = np.unique(g, return_counts=True)
    bg = vals[np.argmax(counts)]

    non_bg = [v for v in vals if v != bg]
    if not non_bg:
        return g

    # The divider/wall color is the non-background color forming the largest
    # connected line structure.
    wall = None
    best = -1
    for v in non_bg:
        n = int(np.sum(g == v))
        if n > best:
            best = n
            wall = v

    out = g.copy()
    open_cell = (g != wall)
    seen = np.zeros((h, w), dtype=bool)
    dirs4 = [(1, 0), (-1, 0), (0, 1), (0, -1)]
    dirs8 = [(dr, dc) for dr in (-1, 0, 1) for dc in (-1, 0, 1) if dr or dc]

    for sr in range(h):
        for sc in range(w):
            if seen[sr, sc] or not open_cell[sr, sc]:
                continue

            comp = []
            q = [(sr, sc)]
            seen[sr, sc] = True
            qi = 0
            while qi < len(q):
                r, c = q[qi]
                qi += 1
                comp.append((r, c))
                for dr, dc in dirs4:
                    nr, nc = r + dr, c + dc
                    if 0 <= nr < h and 0 <= nc < w and open_cell[nr, nc] and not seen[nr, nc]:
                        seen[nr, nc] = True
                        q.append((nr, nc))

            in_comp = np.zeros((h, w), dtype=bool)
            for r, c in comp:
                in_comp[r, c] = True

            boundary = []
            for r, c in comp:
                b = (r == 0 or r == h - 1 or c == 0 or c == w - 1)
                if not b:
                    for dr, dc in dirs8:
                        nr, nc = r + dr, c + dc
                        if 0 <= nr < h and 0 <= nc < w and g[nr, nc] == wall:
                            b = True
                            break
                if b:
                    boundary.append((r, c))

            dist = -np.ones((h, w), dtype=int)
            frontier = []
            for p in boundary:
                dist[p] = 0
                frontier.append(p)

            qi = 0
            while qi < len(frontier):
                r, c = frontier[qi]
                qi += 1
                for dr, dc in dirs4:
                    nr, nc = r + dr, c + dc
                    if 0 <= nr < h and 0 <= nc < w and in_comp[nr, nc] and dist[nr, nc] < 0:
                        dist[nr, nc] = dist[r, c] + 1
                        frontier.append((nr, nc))

            by_depth = {}
            for r, c in comp:
                col = g[r, c]
                if col != bg and col != wall:
                    d = dist[r, c]
                    if d not in by_depth:
                        by_depth[d] = col

            if not by_depth:
                continue

            palette = []
            if 0 not in by_depth:
                palette.append(bg)
            for d in sorted(by_depth):
                palette.append(by_depth[d])

            for r, c in comp:
                out[r, c] = palette[dist[r, c] % len(palette)]

    return out

