def transform(grid):
    bg = np.bincount(grid.ravel()).argmax()
    h, w = grid.shape

    best = None
    for col in np.unique(grid):
        if col == bg:
            continue
        for r1 in range(h):
            for r2 in range(r1 + 2, h):
                cs = np.where((grid[r1] == col) & (grid[r2] == col))[0]
                for i in range(len(cs)):
                    c1 = int(cs[i])
                    for c2 in cs[i + 1:]:
                        c2 = int(c2)
                        if c2 <= c1 + 1:
                            continue
                        if (np.all(grid[r1, c1:c2 + 1] == col) and
                            np.all(grid[r2, c1:c2 + 1] == col) and
                            np.all(grid[r1:r2 + 1, c1] == col) and
                            np.all(grid[r1:r2 + 1, c2] == col)):
                            inside = grid[r1 + 1:r2, c1 + 1:c2]
                            if inside.size and len(np.unique(inside)) == 1:
                                area = (r2 - r1 + 1) * (c2 - c1 + 1)
                                if best is None or area > best[0]:
                                    best = (area, r1, r2, c1, c2, col, int(inside[0, 0]))

    _, r1, r2, c1, c2, frame, fill = best
    out_h, out_w = r2 - r1 - 1, c2 - c1 - 1
    out = np.full((out_h, out_w), fill, dtype=grid.dtype)

    blocked = np.zeros_like(grid, dtype=bool)
    blocked[r1:r2 + 1, c1:c2 + 1] = True
    vis = (grid != bg) & (~blocked)

    groups = []

    for col in np.unique(grid[vis]):
        pts = [(int(r), int(c), int(grid[r, c])) for r, c in zip(*np.where(vis & (grid == col)))]
        if pts:
            groups.append(pts)

    seen = np.zeros_like(grid, dtype=bool)
    for sr, sc in zip(*np.where(vis)):
        if seen[sr, sc]:
            continue
        stack = [(int(sr), int(sc))]
        seen[sr, sc] = True
        pts = []
        while stack:
            rr, cc = stack.pop()
            pts.append((rr, cc, int(grid[rr, cc])))
            for dr, dc in ((1, 0), (-1, 0), (0, 1), (0, -1)):
                nr, nc = rr + dr, cc + dc
                if 0 <= nr < h and 0 <= nc < w and vis[nr, nc] and not seen[nr, nc]:
                    seen[nr, nc] = True
                    stack.append((nr, nc))
        if pts:
            groups.append(pts)

    def has_adjacent(values):
        s = set(values)
        return any(v + 1 in s for v in s)

    def alt_row_value(vals, pos, start):
        vals = sorted(vals)
        colors = sorted(set(v for _, v in vals))
        if len(colors) == 1:
            return colors[0]
        anchor = vals[-1][1]
        other = colors[0] if colors[1] == anchor else colors[1]
        return anchor if (pos - start) % 2 == 0 else other

    def alt_col_value(vals, pos, start, existing):
        colors = sorted(set(v for _, v in vals))
        if len(colors) == 1:
            return colors[0]
        if existing != fill:
            anchor = int(existing)
        else:
            above = [(r, v) for r, v in vals if r < start]
            if above:
                last = max(above)[1]
                anchor = colors[0] if colors[1] == last else colors[1]
            else:
                below = [(r, v) for r, v in vals if r > start]
                anchor = min(below)[1] if below else vals[0][1]
        other = colors[0] if colors[1] == anchor else colors[1]
        return anchor if (pos - start) % 2 == 0 else other

    for pts in groups:
        rs = [p[0] for p in pts]
        cs = [p[1] for p in pts]
        gr1, gr2, gc1, gc2 = min(rs), max(rs), min(cs), max(cs)

        row_vals = {}
        col_vals = {}
        for rr, cc, v in pts:
            row_vals.setdefault(rr, []).append((cc, v))
            col_vals.setdefault(cc, []).append((rr, v))

        for rr, vals in row_vals.items():
            if not (r1 < rr < r2):
                continue
            if not has_adjacent([c for c, _ in vals]):
                continue
            a, b = max(c1 + 1, gc1), min(c2 - 1, gc2)
            if a > b:
                continue
            for cc in range(a, b + 1):
                out[rr - r1 - 1, cc - c1 - 1] = alt_row_value(vals, cc, a)

        for cc, vals in col_vals.items():
            if not (c1 < cc < c2):
                continue
            if not has_adjacent([r for r, _ in vals]):
                continue
            a, b = max(r1 + 1, gr1), min(r2 - 1, gr2)
            if a > b:
                continue
            for rr in range(a, b + 1):
                oi, oj = rr - r1 - 1, cc - c1 - 1
                out[oi, oj] = alt_col_value(vals, rr, a, out[oi, oj])

    return out

def transform(grid):
    h, w = grid.shape
    out = grid.copy()
    bg = 4
    obj = 1

    seen = np.zeros((h, w), dtype=bool)
    dirs4 = [(1, 0), (-1, 0), (0, 1), (0, -1)]
    dirs8 = [(dr, dc) for dr in (-1, 0, 1) for dc in (-1, 0, 1) if dr or dc]

    for sr in range(h):
        for sc in range(w):
            if grid[sr, sc] != obj or seen[sr, sc]:
                continue

            stack = [(sr, sc)]
            seen[sr, sc] = True
            cells = []

            while stack:
                r, c = stack.pop()
                cells.append((r, c))
                for dr, dc in dirs4:
                    nr, nc = r + dr, c + dc
                    if 0 <= nr < h and 0 <= nc < w and not seen[nr, nc] and grid[nr, nc] == obj:
                        seen[nr, nc] = True
                        stack.append((nr, nc))

            comp = set(cells)

            border = set()
            for r, c in cells:
                for dr, dc in dirs8:
                    nr, nc = r + dr, c + dc
                    if 0 <= nr < h and 0 <= nc < w and grid[nr, nc] == bg:
                        border.add((nr, nc))

            outside = np.zeros((h, w), dtype=bool)
            stack = []

            for r in range(h):
                for c in (0, w - 1):
                    if (r, c) not in comp and not outside[r, c]:
                        outside[r, c] = True
                        stack.append((r, c))
            for c in range(w):
                for r in (0, h - 1):
                    if (r, c) not in comp and not outside[r, c]:
                        outside[r, c] = True
                        stack.append((r, c))

            while stack:
                r, c = stack.pop()
                for dr, dc in dirs4:
                    nr, nc = r + dr, c + dc
                    if 0 <= nr < h and 0 <= nc < w and not outside[nr, nc] and (nr, nc) not in comp:
                        outside[nr, nc] = True
                        stack.append((nr, nc))

            holes = []
            for r in range(h):
                for c in range(w):
                    if grid[r, c] == bg and not outside[r, c] and (r, c) not in comp:
                        holes.append((r, c))

            for r, c in border:
                out[r, c] = 2

            if holes:
                for r, c in cells:
                    out[r, c] = 8
                for r, c in holes:
                    out[r, c] = 6

    return out

def transform(grid):
    h, w = grid.shape
    seen = np.zeros((h, w), dtype=bool)
    comps = []

    for r in range(h):
        for c in range(w):
            if grid[r, c] != 0 and not seen[r, c]:
                col = grid[r, c]
                stack = [(r, c)]
                seen[r, c] = True
                cells = []
                while stack:
                    y, x = stack.pop()
                    cells.append((y, x))
                    for dy, dx in ((1, 0), (-1, 0), (0, 1), (0, -1)):
                        ny, nx = y + dy, x + dx
                        if 0 <= ny < h and 0 <= nx < w and not seen[ny, nx] and grid[ny, nx] == col:
                            seen[ny, nx] = True
                            stack.append((ny, nx))
                rs = [p[0] for p in cells]
                cs = [p[1] for p in cells]
                r0, r1, c0, c1 = min(rs), max(rs), min(cs), max(cs)
                mask = np.zeros((r1 - r0 + 1, c1 - c0 + 1), dtype=bool)
                for y, x in cells:
                    mask[y - r0, x - c0] = True
                comps.append({
                    "color": int(col),
                    "cells": cells,
                    "area": len(cells),
                    "bbox": (r0, r1, c0, c1),
                    "mask": mask,
                    "cy": (r0 + r1) / 2,
                    "cx": (c0 + c1) / 2,
                })

    wall = max(comps, key=lambda o: o["area"])
    wr0, wr1, wc0, wc1 = wall["bbox"]
    vertical_wall = (wr1 - wr0 + 1) > (wc1 - wc0 + 1)

    out = np.zeros_like(grid)
    for y, x in wall["cells"]:
        out[y, x] = wall["color"]

    objs = [o for o in comps if o is not wall]
    groups = {}
    for o in objs:
        key = o["mask"].shape[0] if vertical_wall else o["mask"].shape[1]
        groups.setdefault(key, []).append(o)

    def compatible(a, b):
        if vertical_wall:
            return not np.any(a["mask"][:, -1] & b["mask"][:, 0])
        return not np.any(a["mask"][-1, :] & b["mask"][0, :])

    def compose(order):
        if vertical_wall:
            hh = order[0]["mask"].shape[0]
            ww = sum(o["mask"].shape[1] for o in order) - len(order) + 1
            canv = np.zeros((hh, ww), dtype=int)
            x = 0
            for o in order:
                m = o["mask"]
                canv[:, x:x + m.shape[1]][m] = o["color"]
                x += m.shape[1] - 1
        else:
            hh = sum(o["mask"].shape[0] for o in order) - len(order) + 1
            ww = order[0]["mask"].shape[1]
            canv = np.zeros((hh, ww), dtype=int)
            y = 0
            for o in order:
                m = o["mask"]
                canv[y:y + m.shape[0], :][m] = o["color"]
                y += m.shape[0] - 1
        return canv

    def permutations(items):
        if len(items) <= 1:
            return [items]
        res = []
        for i in range(len(items)):
            rest = items[:i] + items[i + 1:]
            for p in permutations(rest):
                res.append([items[i]] + p)
        return res

    for group in groups.values():
        best = None

        for order in permutations(group):
            ok = True
            for i in range(len(order) - 1):
                if not compatible(order[i], order[i + 1]):
                    ok = False
                    break
            if not ok:
                continue

            tile = compose(order)
            th, tw = tile.shape
            ys, xs = np.nonzero(tile)

            for y0 in range(h - th + 1):
                for x0 in range(w - tw + 1):
                    valid = True
                    overlap = 0
                    for yy, xx in zip(ys, xs):
                        y, x = y0 + yy, x0 + xx
                        if out[y, x] != 0:
                            valid = False
                            break
                        if wr0 <= y <= wr1 and wc0 <= x <= wc1:
                            overlap += 1
                    if not valid or overlap == 0:
                        continue

                    if vertical_wall:
                        center_dist = abs((x0 + tw / 2) - ((wc0 + wc1 + 1) / 2))
                        side_dist = abs((y0 + th / 2) - np.mean([o["cy"] for o in group]))
                    else:
                        center_dist = abs((y0 + th / 2) - ((wr0 + wr1 + 1) / 2))
                        side_dist = abs((x0 + tw / 2) - np.mean([o["cx"] for o in group]))

                    score = (overlap, -center_dist, -side_dist)
                    if best is None or score > best[0]:
                        best = (score, tile, y0, x0)

        if best is None:
            continue

        _, tile, y0, x0 = best
        ys, xs = np.nonzero(tile)
        for yy, xx in zip(ys, xs):
            out[y0 + yy, x0 + xx] = tile[yy, xx]

    return out

def transform(grid):
    g = grid.copy()
    h, w = g.shape
    bg = 8

    sep_rows = [r for r in range(h) if len(set(g[r].tolist())) == 1 and g[r, 0] != bg]
    first_sep = sep_rows[0]
    last_sep = sep_rows[-1]

    obj_rows = [
        r for r in range(h)
        if r not in sep_rows and np.any((g[r] != bg) & (g[r] != g[first_sep, 0]))
    ]
    row_runs = []
    for r in obj_rows:
        if not row_runs or r != row_runs[-1][-1] + 1:
            row_runs.append([r])
        else:
            row_runs[-1].append(r)

    obj_cols = [
        c for c in range(w)
        if np.any((g[:, c] != bg) & (g[:, c] != g[first_sep, 0]))
    ]
    col_runs = []
    for c in obj_cols:
        if not col_runs or c != col_runs[-1][-1] + 1:
            col_runs.append([c])
        else:
            col_runs[-1].append(c)

    top_run = row_runs[0]
    cat_runs = row_runs[1:]
    query = []
    for cr in col_runs:
        q = g[top_run[0]:top_run[0] + 3, cr[0]:cr[0] + 3].copy()
        if np.any(q != bg):
            query.append(q)

    selected = []
    for ri, rr in enumerate(cat_runs):
        for ci, cr in enumerate(col_runs):
            cell = g[rr[0]:rr[0] + 3, cr[0]:cr[0] + 3]
            for q in query:
                if cell.shape == q.shape and np.array_equal(cell, q):
                    selected.append((ri, ci))
                    break

    if selected:
        rows = [p[0] for p in selected]
        cols = [p[1] for p in selected]
        line = (
            len(selected) == len(col_runs) and len(set(rows)) == 1
        ) or (
            len(selected) == len(cat_runs) and len(set(cols)) == 1
        )
    else:
        line = False

    for ri, ci in selected:
        rr = cat_runs[ri]
        cr = col_runs[ci]
        r0, r1 = max(0, rr[0] - 1), min(h, rr[-1] + 2)
        c0, c1 = max(0, cr[0] - 1), min(w, cr[-1] + 2)
        block = g[r0:r1, c0:c1]
        block[block == bg] = 3

    if line:
        top = g[:first_sep, :]
        top[top == bg] = 3

        if len(set([p[0] for p in selected])) == 1:
            line_row = selected[0][0]
            for qi, q in enumerate(query):
                for ri, ci in selected:
                    if ci == qi and np.array_equal(q, grid[cat_runs[ri][0]:cat_runs[ri][0] + 3,
                                                        col_runs[ci][0]:col_runs[ci][0] + 3]):
                        nr = ri + 1
                        if nr < len(cat_runs):
                            rr = top_run
                            cr = col_runs[qi]
                            repl = grid[cat_runs[nr][0]:cat_runs[nr][0] + 3,
                                        cr[0]:cr[0] + 3]
                            g[rr[0]:rr[0] + 3, cr[0]:cr[0] + 3] = repl.copy()
                            top = g[:first_sep, :]
                            top[top == bg] = 3
                        break

    fill = 3 if line else 2
    if selected and last_sep + 1 < h:
        g[last_sep + 1:, :] = fill

    return g

