def transform(grid):
    g = grid.copy()
    h, w = g.shape
    bg = 0
    paint = 1

    def components(color):
        seen = np.zeros((h, w), dtype=bool)
        out = []
        for r in range(h):
            for c in range(w):
                if g[r, c] == color and not seen[r, c]:
                    stack = [(r, c)]
                    seen[r, c] = True
                    cells = []
                    while stack:
                        rr, cc = stack.pop()
                        cells.append((rr, cc))
                        for dr, dc in ((1, 0), (-1, 0), (0, 1), (0, -1)):
                            nr, nc = rr + dr, cc + dc
                            if 0 <= nr < h and 0 <= nc < w and not seen[nr, nc] and g[nr, nc] == color:
                                seen[nr, nc] = True
                                stack.append((nr, nc))
                    out.append(cells)
        return out

    anchors = np.zeros((h, w), dtype=bool)
    fill = np.zeros((h, w), dtype=bool)

    for color in [x for x in np.unique(g) if x not in (bg, paint)]:
        for cells in components(color):
            s = set(cells)
            rows = {}
            cols = {}
            for r, c in cells:
                rows.setdefault(r, []).append(c)
                cols.setdefault(c, []).append(r)

            made = False

            for r, cs in rows.items():
                if len(cs) >= 2:
                    a, b = min(cs), max(cs)
                    if any(g[r, c] == bg for c in range(a + 1, b)):
                        made = True
                        for c in range(a + 1, b):
                            if g[r, c] == bg:
                                fill[r, c] = True

            for c, rs in cols.items():
                if len(rs) >= 2:
                    a, b = min(rs), max(rs)
                    if any(g[r, c] == bg for r in range(a + 1, b)):
                        made = True
                        for r in range(a + 1, b):
                            if g[r, c] == bg:
                                fill[r, c] = True

            row_items = sorted((r, min(cs), max(cs)) for r, cs in rows.items())
            for i in range(len(row_items)):
                r1, a1, b1 = row_items[i]
                for j in range(i + 1, len(row_items)):
                    r2, a2, b2 = row_items[j]
                    a, b = max(a1, a2), min(b1, b2)
                    if a > b:
                        continue
                    if all((rr, a) in s or (rr, b) in s for rr in range(r1, r2 + 1)):
                        for rr in range(r1 + 1, r2):
                            for cc in range(a, b + 1):
                                if g[rr, cc] == bg:
                                    fill[rr, cc] = True
                                    made = True

            col_items = sorted((c, min(rs), max(rs)) for c, rs in cols.items())
            for i in range(len(col_items)):
                c1, a1, b1 = col_items[i]
                for j in range(i + 1, len(col_items)):
                    c2, a2, b2 = col_items[j]
                    a, b = max(a1, a2), min(b1, b2)
                    if a > b:
                        continue
                    if all((a, cc) in s or (b, cc) in s for cc in range(c1, c2 + 1)):
                        for rr in range(a, b + 1):
                            for cc in range(c1 + 1, c2):
                                if g[rr, cc] == bg:
                                    fill[rr, cc] = True
                                    made = True

            if made:
                for r, c in cells:
                    anchors[r, c] = True

