        seen_border = False
        for c in range(w):
            if anchors[r, c]:
                seen_border = True
            elif seen_border and g[r, c] == paint:
                fill[r, c] = True

    out = g.copy()
    for r in range(h):
        for c in range(w):
            if out[r, c] == paint and not fill[r, c]:
                out[r, c] = bg
            elif fill[r, c] and out[r, c] == bg:
                out[r, c] = paint

    return out

def transform(grid):
    h, w = grid.shape
    out = grid.copy()

    colors = [c for c in np.unique(grid) if c != 0]

    def comps_for_color(color):
        seen = np.zeros((h, w), dtype=bool)
        comps = []
        for r in range(h):
            for c in range(w):
                if grid[r, c] == color and not seen[r, c]:
                    q = [(r, c)]
                    seen[r, c] = True
                    comp = []
                    for rr, cc in q:
                        comp.append((rr, cc))
                        for dr, dc in ((1, 0), (-1, 0), (0, 1), (0, -1)):
                            nr, nc = rr + dr, cc + dc
                            if 0 <= nr < h and 0 <= nc < w and not seen[nr, nc] and grid[nr, nc] == color:
                                seen[nr, nc] = True
                                q.append((nr, nc))
                    comps.append(comp)
        return comps

    host_comps = []
    for color in colors:
        for comp in comps_for_color(color):
            if len(comp) >= 3:
                host_comps.append((color, comp, set(comp)))

    moves = []
    for host_color, comp, comp_set in host_comps:
        other = set()
        for r, c in comp:
            for dr, dc in ((1, 0), (-1, 0), (0, 1), (0, -1)):
                nr, nc = r + dr, c + dc
                if 0 <= nr < h and 0 <= nc < w:
                    v = grid[nr, nc]
                    if v != 0 and v != host_color:
                        other.add((nr, nc, int(v)))

        if not other:
            continue

        by_color = {}
        for r, c, v in other:
            by_color.setdefault(v, set()).add((r, c))

        rs = [p[0] for p in comp]
        cs = [p[1] for p in comp]
        top, bot, left, right = min(rs), max(rs), min(cs), max(cs)

        sides = [
            ("up", top, [(r, c) for r, c in comp if r == top]),
            ("down", h - 1 - bot, [(r, c) for r, c in comp if r == bot]),
            ("left", left, [(r, c) for r, c in comp if c == left]),
            ("right", w - 1 - right, [(r, c) for r, c in comp if c == right]),
        ]

        for color, cells in by_color.items():
            cr = sum(r for r, c in cells) / len(cells)
            cc = sum(c for r, c in cells) / len(cells)

            best = None
            for side, dist, edge_cells in sides:
                if dist <= 0:
                    continue
                if side in ("up", "down"):
                    er, ec = min(edge_cells, key=lambda p: (abs(p[1] - cc), abs(p[0] - cr)))
                else:
                    er, ec = min(edge_cells, key=lambda p: (abs(p[0] - cr), abs(p[1] - cc)))
                score = (dist, abs(ec - cc) if side in ("up", "down") else abs(er - cr))
                if best is None or score < best[0]:
                    best = (score, side, er, ec, dist)

            if best is None:
                continue

            _, side, er, ec, dist = best
            n = min(len(cells), dist)

            for r, c in cells:
                out[r, c] = 0

            for i in range(1, n + 1):
                if side == "up":
                    out[er - i, ec] = color
                elif side == "down":
                    out[er + i, ec] = color
                elif side == "left":
                    out[er, ec - i] = color
                else:
                    out[er, ec + i] = color

    return out

def transform(grid):
    out = grid.copy()
    h, w = out.shape

    out[out == 3] = 8
    centers = {}

    for r in range(h):
        c = 0
        while c < w:
            if grid[r, c] == 7:
                start = c
                while c < w and grid[r, c] == 7:
                    c += 1
                if c - start == 3:
                    mid = start + 1
                    centers.setdefault(r, []).append(mid)
                    for cc in range(start, c):
                        out[r, cc] = 6 if cc == mid else 8
                    for rr in (r - 1, r + 1):
                        if 0 <= rr < h and grid[rr, mid] != 0:
                            out[rr, mid] = 6
                continue
            c += 1

    for r in range(0, h, 2):
        c = 0
        while c < w:
            if grid[r, c] == 0:
                c += 1
                continue

            lo = c
            while c < w and grid[r, c] != 0:
                c += 1
            hi = c - 1

            above = [x for x in centers.get(r - 1, []) if lo <= x <= hi and grid[r, x] != 0]
            below = [x for x in centers.get(r + 1, []) if lo <= x <= hi and grid[r, x] != 0]

            sides = []
            doubled = bool(above and below)

            if above and below:
                mina, maxa = min(above), max(above)
                minb, maxb = min(below), max(below)

                if mina < minb and maxa > maxb:
                    sides = ["left", "right"]
                elif mina > minb and maxa < maxb:
                    sides = []
                elif mina < minb and maxa <= maxb:
                    sides = ["left"]
                elif mina >= minb and maxa > maxb:
                    sides = ["right"]

            elif above and not below:
                sides = ["left"]
                if hi == w - 1:
                    sides.append("right")

            elif not above and not below:
                if grid[r, lo] == 3:
                    sides.append("left")
                if hi != lo and grid[r, hi] == 3:
                    sides.append("right")

            for side in sides:
                if side == "left":
                    out[r, lo] = 3
                    if doubled and lo == 0 and hi == w - 1 and lo + 1 <= hi:
                        out[r, lo + 1] = 3
                else:
                    out[r, hi] = 3
                    if doubled and lo == 0 and hi == w - 1 and hi - 1 >= lo:
                        out[r, hi - 1] = 3

    return out

def transform(grid):
    g = grid
    rows = np.where(np.any(g != 0, axis=1))[0]

    best_start = best_end = rows[0]
    start = prev = rows[0]
    for r in rows[1:]:
        if r == prev + 1:
            prev = r
        else:
            if prev - start > best_end - best_start:
                best_start, best_end = start, prev
            start = prev = r
    if prev - start > best_end - best_start:
        best_start, best_end = start, prev

    r0, r1 = best_start, best_end
    cols = np.where(np.any(g[r0:r1 + 1] != 0, axis=0))[0]
    c0, c1 = cols[0], cols[-1]

    crop = g[r0:r1 + 1, c0:c1 + 1]
    h, w = crop.shape
    out = np.zeros_like(crop)

    outside_rect = np.ones(g.shape, dtype=bool)
    outside_rect[r0:r1 + 1, c0:c1 + 1] = False

    for color in np.unique(crop):
        if color == 0:
            continue

        mask = crop == color
        pts = np.argwhere((g == color) & outside_rect)

        if len(pts):
            rr0, cc0 = pts.min(axis=0)
            rr1, cc1 = pts.max(axis=0)

            above = rr1 < r0
            below = rr0 > r1
            left = cc1 < c0
            right = cc0 > c1

            diagonal = (above or below) and (left or right)
            ph = rr1 - rr0 + 1
            pw = cc1 - cc0 + 1

            if diagonal:
                if len(pts) == 1:
                    if (below and left) or (above and right):
                        mask = np.rot90(mask, -1)
                    else:
                        mask = np.rot90(mask, 1)
                elif ph > pw:
                    mask = np.flipud(np.fliplr(mask))
                elif pw > ph:
                    mask = np.flipud(mask)
                else:
                    mask = np.flipud(np.fliplr(mask))
            else:
                if left or right:
                    mask = np.fliplr(mask)
                if above or below:
                    mask = np.flipud(mask)

        out[mask] = color

    return out

def transform(grid):
    bg = np.bincount(grid.ravel(), minlength=10).argmax()
    vals = [v for v in np.unique(grid) if v != bg]
    if not vals:
        return grid.copy()
    col = vals[0]

    h, w = grid.shape
    fg = grid == col
    out = np.full_like(grid, bg)

    orth = np.zeros_like(fg, dtype=bool)
    orth[:, 1:] |= fg[:, 1:] & fg[:, :-1]
    orth[:, :-1] |= fg[:, :-1] & fg[:, 1:]
    orth[1:, :] |= fg[1:, :] & fg[:-1, :]
    orth[:-1, :] |= fg[:-1, :] & fg[1:, :]

    diag = np.zeros_like(fg, dtype=bool)
    for dr, dc in ((-1, -1), (-1, 1), (1, -1), (1, 1)):
        a = fg[max(0, dr):h + min(0, dr), max(0, dc):w + min(0, dc)]
        b = diag[max(0, -dr):h - max(0, dr), max(0, -dc):w - max(0, dc)]
        b |= a

    major_row = np.zeros(h, dtype=bool)
    for r in range(h):
        run = 0
        for c in range(w):
            if fg[r, c]:
                run += 1
                if run >= 3:
                    major_row[r] = True
            else:
                run = 0

    major_col = np.zeros(w, dtype=bool)
    for c in range(w):
        run = 0
        for r in range(h):
            if fg[r, c]:
                run += 1
                if run >= 3:
                    major_col[c] = True
            else:
                run = 0

    keep = orth | (fg & ~diag & (major_row[:, None] | major_col[None, :]))
    out[keep] = col

    def row_support(r, a, b):
        for rr in (r - 1, r + 1):
            if 0 <= rr < h:
                if a + 1 < w and fg[rr, a + 1]:
                    return True
                if b - 1 >= 0 and fg[rr, b - 1]:
                    return True
        return False

    def col_support(c, a, b):
        for rr in (a, a + 1, b - 1, b):
            if 0 <= rr < h:
                for cc in range(max(0, c - 2), min(w, c + 3)):
                    if cc != c and fg[rr, cc]:
                        return True
        return False

    for r in range(h):
        xs = np.flatnonzero(out[r] == col)
        if len(xs) < 2:
            continue
        for a, b in zip(xs[:-1], xs[1:]):
            if 1 < b - a <= 4 and row_support(r, a, b):
                out[r, a:b + 1] = col

    for c in range(w):
        ys = np.flatnonzero(out[:, c] == col)
        if len(ys) < 2:
            continue
        for a, b in zip(ys[:-1], ys[1:]):
            if 1 < b - a <= 5 and col_support(c, a, b):
                out[a:b + 1, c] = col

    return out

def transform(grid):
    bg = np.bincount(grid.ravel(), minlength=10).argmax()
    h, w = grid.shape

    seen = np.zeros((h, w), dtype=bool)
    comps = []

    for r in range(h):
        for c in range(w):
            if seen[r, c] or grid[r, c] == bg:
                continue

            color = grid[r, c]
            stack = [(r, c)]
            seen[r, c] = True
            cells = []

            while stack:
                x, y = stack.pop()
                cells.append((x, y))
                for dx in (-1, 0, 1):
                    for dy in (-1, 0, 1):
                        if dx == 0 and dy == 0:
                            continue
                        nx, ny = x + dx, y + dy
                        if (
                            0 <= nx < h and 0 <= ny < w
                            and not seen[nx, ny]
                            and grid[nx, ny] == color
                        ):
                            seen[nx, ny] = True
                            stack.append((nx, ny))

            rs = [p[0] for p in cells]
            cs = [p[1] for p in cells]
            comps.append({
                "color": color,
                "cells": cells,
                "r0": min(rs),
                "r1": max(rs),
                "c0": min(cs),
                "c1": max(cs),
            })

    zero_comps = [c for c in comps if c["color"] == 0]
    panel = max(zero_comps, key=lambda c: len(c["cells"]))

    pr0, pr1, pc0, pc1 = panel["r0"], panel["r1"], panel["c0"], panel["c1"]
    out = np.zeros((pr1 - pr0 + 1, pc1 - pc0 + 1), dtype=int)

    panel_colors = []
    for r in range(pr0, pr1 + 1):
        for c in range(pc0, pc1 + 1):
            val = grid[r, c]
            if val != 0 and val != bg and val not in panel_colors:
                panel_colors.append(val)

    for color in panel_colors:
        marker_positions = np.argwhere(grid[pr0:pr1 + 1, pc0:pc1 + 1] == color)
        if len(marker_positions) == 0:
            continue

        mr = int(marker_positions[0, 0])
        mc = int(marker_positions[0, 1])

        count = 0
        for comp in comps:
            if comp["color"] != color:
                continue
            inside_panel = (
                pr0 <= comp["r0"] <= pr1 and pr0 <= comp["r1"] <= pr1
                and pc0 <= comp["c0"] <= pc1 and pc0 <= comp["c1"] <= pc1
            )
            if not inside_panel:
                count += 1

        for i in range(count):
            col = mc + 2 * i
            if col < out.shape[1]:
                out[mr, col] = color

    return out

def transform(grid):
    H, W = grid.shape

    pats = [
        ("up",    (2, 3), [(0, 1), (1, 0), (1, 1), (1, 2)], (1, 1), (0, 1), (-1, 0)),
        ("down",  (2, 3), [(0, 0), (0, 1), (0, 2), (1, 1)], (0, 1), (1, 1), (1, 0)),
        ("left",  (3, 2), [(0, 1), (1, 0), (1, 1), (2, 1)], (1, 1), (1, 0), (0, -1)),
        ("right", (3, 2), [(0, 0), (1, 0), (1, 1), (2, 0)], (1, 0), (1, 1), (0, 1)),
    ]

    markers = []
    marked = set()

    for _, (ph, pw), cells, joint, tip, delta in pats:
        allcells = {(r, c) for r in range(ph) for c in range(pw)}
        offcells = list(allcells - set(cells))
        for r in range(H - ph + 1):
            for c in range(W - pw + 1):
                ok = True
                pos = [(r + a, c + b) for a, b in cells]
                joint_pos = (r + joint[0], c + joint[1])

                for a, b in cells:
                    rr, cc = r + a, c + b
                    if (rr, cc) == joint_pos:
                        continue
                    if grid[rr, cc] != 1:
