                    continue

                for a, b in offcells:
                    if grid[r + a, c + b] == 1:
                        ok = False
                        break
                if not ok:
                    continue

                key = tuple(sorted(pos))
                if key in marked:
                    continue
                marked.add(key)
                markers.append({
                    "cells": pos,
                    "joint": joint_pos,
                    "tip": (r + tip[0], c + tip[1]),
                    "delta": delta,
                })

