    cid = 0
    for r in range(H):
        for c in range(W):
            if comp[r, c] != -1:
                continue
            col = int(clean[r, c])
            q = [(r, c)]
            comp[r, c] = cid
            cells = []
            while q:
                x, y = q.pop()
                cells.append((x, y))
                for dx, dy in ((1, 0), (-1, 0), (0, 1), (0, -1)):
                    nx, ny = x + dx, y + dy
                    if 0 <= nx < H and 0 <= ny < W and comp[nx, ny] == -1 and int(clean[nx, ny]) == col:
                        comp[nx, ny] = cid
                        q.append((nx, ny))
            comps.append(cells)
            cid += 1

    out = clean.copy()

    for m in markers:
        jr, jc = m["joint"]
        if int(grid[jr, jc]) != 1:
            src = int(grid[jr, jc])
        else:
            src = int(clean[jr, jc])

        dr, dc = m["delta"]
        rr, cc = m["tip"][0] + dr, m["tip"][1] + dc
        while 0 <= rr < H and 0 <= cc < W and (rr, cc) in marker_cells:
            rr += dr
            cc += dc

        if 0 <= rr < H and 0 <= cc < W:
            target = comp[rr, cc]
            for x, y in comps[target]:
                out[x, y] = src

    if H != W:
        out = out.T

    return out

