    patterns = {}

    for color in colors:
        loc = np.argwhere((grid == color) & (~large_mask))
        if loc.size == 0:
            continue

        r0, c0 = loc.min(axis=0)
        r1, c1 = loc.max(axis=0)

        if r1 - r0 <= 2 and c1 - c0 <= 2:
            pat = np.zeros((3, 3), dtype=bool)
            for r, c in loc:
                pat[int(r - r0), int(c - c0)] = True
            patterns[color] = pat

    min_r = min(r for r, c, color in large) - 1
    max_r = max(r + 4 for r, c, color in large) + 1
    min_c = min(c for r, c, color in large) - 1
    max_c = max(c + 4 for r, c, color in large) + 1

    out = grid[min_r:max_r + 1, min_c:max_c + 1].copy()

