def transform(grid):
    bg = np.bincount(grid.ravel()).argmax()
    h, w = grid.shape

    seen = np.zeros((h, w), dtype=bool)
    comps = []
    for r in range(h):
        for c in range(w):
            if seen[r, c] or grid[r, c] == bg:
                continue
            col = grid[r, c]
            stack = [(r, c)]
            seen[r, c] = True
            cells = []
            while stack:
                rr, cc = stack.pop()
                cells.append((rr, cc))
                for dr, dc in ((1, 0), (-1, 0), (0, 1), (0, -1)):
                    nr, nc = rr + dr, cc + dc
                    if 0 <= nr < h and 0 <= nc < w and not seen[nr, nc] and grid[nr, nc] == col:
                        seen[nr, nc] = True
                        stack.append((nr, nc))
            rs = [p[0] for p in cells]
            cs = [p[1] for p in cells]
            comps.append({
                "color": col,
                "cells": cells,
                "area": len(cells),
                "r0": min(rs), "r1": max(rs),
                "c0": min(cs), "c1": max(cs),
                "rc": sum(rs) / len(rs),
                "cc": sum(cs) / len(cs),
            })

    markers = [c for c in comps if c["area"] == 2]
    out = np.full_like(grid, bg)
    if not markers:
        return out

    center_r = sum(c["rc"] for c in markers) / len(markers)
    center_c = sum(c["cc"] for c in markers) / len(markers)

    by_color = {}
    for comp in comps:
        by_color.setdefault(comp["color"], []).append(comp)

    def mask_for(comp):
        mh = comp["r1"] - comp["r0"] + 1
        mw = comp["c1"] - comp["c0"] + 1
        m = np.zeros((mh, mw), dtype=bool)
        for rr, cc in comp["cells"]:
            m[rr - comp["r0"], cc - comp["c0"]] = True
        return m

    def variants(mask):
        res = []
        for flip in (False, True):
            base = np.fliplr(mask) if flip else mask
            for k in range(4):
                m = np.rot90(base, k)
                if not any(m.shape == x.shape and np.array_equal(m, x) for x in res):
                    res.append(m)
        return res

    def side_indices(mask, side):
        if side == "left":
            return np.where(mask[:, 0])[0]
        if side == "right":
            return np.where(mask[:, -1])[0]
        if side == "top":
            return np.where(mask[0, :])[0]
        return np.where(mask[-1, :])[0]

    for marker in markers:
        for rr, cc in marker["cells"]:
            out[rr, cc] = marker["color"]

        objects = [c for c in by_color.get(marker["color"], []) if c is not marker and c["area"] > 2]
        if not objects:
            continue
        obj = max(objects, key=lambda c: c["area"])
        base = mask_for(obj)

        if abs(marker["cc"] - center_c) > abs(marker["rc"] - center_r):
            direction = "left" if marker["cc"] < center_c else "right"
        else:
            direction = "top" if marker["rc"] < center_r else "bottom"

        facing = {"left": "right", "right": "left", "top": "bottom", "bottom": "top"}[direction]
        need = marker["area"]
        best = None

        for m in variants(base):
            idx = side_indices(m, facing)
            if len(idx) != need:
                continue
            if need > 1 and not np.all(np.diff(idx) == 1):
                continue

            mh, mw = m.shape
            if direction in ("left", "right"):
                centered = abs(idx.mean() - (mh - 1) / 2)
                top = marker["r0"] - int(idx.min())
                left = marker["c0"] - mw if direction == "left" else marker["c1"] + 1
            else:
                centered = abs(idx.mean() - (mw - 1) / 2)
                top = marker["r0"] - mh if direction == "top" else marker["r1"] + 1
                left = marker["c0"] - int(idx.min())

            rr_idx, cc_idx = np.where(m)
            in_bounds = np.all((0 <= top + rr_idx) & (top + rr_idx < h) &
                               (0 <= left + cc_idx) & (left + cc_idx < w))
            score = (centered, 0 if in_bounds else 1, abs(mh - mw))
            if best is None or score < best[0]:
                best = (score, m, top, left)

        if best is None:
            continue

        _, m, top, left = best
        rr_idx, cc_idx = np.where(m)
        for a, b in zip(rr_idx, cc_idx):
            nr, nc = top + a, left + b
            if 0 <= nr < h and 0 <= nc < w:
                out[nr, nc] = marker["color"]

    return out

def transform(grid):
    out = grid.copy()
    h, w = grid.shape

    p = np.argwhere(grid == 2)[0]
    cr, cc = int(p[0]), int(p[1])

    obj_rows = range(cr - 1, cr + 2)
    obj_cols = range(cc - 1, cc + 2)

    bg = 7
    guide = 6
    mark = 9

    # The 6-cells form a stencil around the central 3x3 object.  A 9 that touches
    # this stencil is only a signal and is erased from its old position.
    signal = np.zeros((h, w), dtype=bool)
    for r in range(h):
        for c in range(w):
            if grid[r, c] == mark:
                for dr in (-1, 0, 1):
                    for dc in (-1, 0, 1):
                        rr, cc2 = r + dr, c + dc
                        if 0 <= rr < h and 0 <= cc2 < w and grid[rr, cc2] == guide:
                            signal[r, c] = True

    for r in range(h):
        for c in range(w):
            if signal[r, c]:
                out[r, c] = bg

    def has_signal_from(r, c, dr, dc):
        rr, cc2 = r + dr, c + dc
        while 0 <= rr < h and 0 <= cc2 < w:
            if signal[rr, cc2]:
                return True
            if grid[rr, cc2] == guide:
                return False
            rr += dr
            cc2 += dc
        return False

    any_guide = np.any(grid == guide)

    if not any_guide:
        # With no stencil, the loose 9s indicate the upper/left side of the object.
        for r in range(h):
            for c in range(w):
                if grid[r, c] == mark:
                    out[r, c] = bg
        for c in obj_cols:
            out[cr - 1, c] = mark
        out[cr, cc - 1] = mark
        return out

    # Paint object cells reached by signals from their outward directions.
    painted = set()
    for r in obj_rows:
        for c in obj_cols:
            if r == cr and c == cc:
                continue
            dr = 0 if r == cr else (1 if r > cr else -1)
            dc = 0 if c == cc else (1 if c > cc else -1)
            if has_signal_from(r, c, dr, dc):
                painted.add((r, c))

    # If the stencil has signals on several sides, the whole 3x3 kernel is filled.
    sides = set()
    for r, c in np.argwhere(signal):
        r, c = int(r), int(c)
        if r < cr - 1:
            sides.add("N")
        if r > cr + 1:
            sides.add("S")
        if c < cc - 1:
            sides.add("W")
        if c > cc + 1:
            sides.add("E")

    if len(sides) >= 3:
        for r in obj_rows:
            for c in obj_cols:
                out[r, c] = mark
    else:
        for r, c in painted:
            out[r, c] = mark

    return out

def transform(grid):
    out = grid.copy()
    h, w = grid.shape

    p = np.argwhere(grid == 2)[0]
    cr, cc = int(p[0]), int(p[1])

    obj_rows = range(cr - 1, cr + 2)
    obj_cols = range(cc - 1, cc + 2)

    bg = 7
    guide = 6
    mark = 9

    # The 6-cells form a stencil around the central 3x3 object.  A 9 that touches
    # this stencil is only a signal and is erased from its old position.
    signal = np.zeros((h, w), dtype=bool)
    for r in range(h):
        for c in range(w):
            if grid[r, c] == mark:
                for dr in (-1, 0, 1):
                    for dc in (-1, 0, 1):
                        rr, cc2 = r + dr, c + dc
                        if 0 <= rr < h and 0 <= cc2 < w and grid[rr, cc2] == guide:
                            signal[r, c] = True

    for r in range(h):
        for c in range(w):
            if signal[r, c]:
                out[r, c] = bg

    def has_signal_from(r, c, dr, dc):
        rr, cc2 = r + dr, c + dc
        while 0 <= rr < h and 0 <= cc2 < w:
            if signal[rr, cc2]:
                return True
            if grid[rr, cc2] == guide:
                return False
            rr += dr
            cc2 += dc
        return False

    any_guide = np.any(grid == guide)

    if not any_guide:
        # With no stencil, the loose 9s indicate the upper/left side of the object.
        for r in range(h):
            for c in range(w):
                if grid[r, c] == mark:
                    out[r, c] = bg
        for c in obj_cols:
            out[cr - 1, c] = mark
        out[cr, cc - 1] = mark
        return out

    # Paint object cells reached by signals from their outward directions.
    painted = set()
    for r in obj_rows:
        for c in obj_cols:
            if r == cr and c == cc:
                continue
            dr = 0 if r == cr else (1 if r > cr else -1)
            dc = 0 if c == cc else (1 if c > cc else -1)
            if has_signal_from(r, c, dr, dc):
                painted.add((r, c))

    # If the stencil has signals on several sides, the whole 3x3 kernel is filled.
    sides = set()
    for r, c in np.argwhere(signal):
        r, c = int(r), int(c)
        if r < cr - 1:
            sides.add("N")
        if r > cr + 1:
            sides.add("S")
        if c < cc - 1:
            sides.add("W")
        if c > cc + 1:
            sides.add("E")

    if len(sides) >= 3:
        for r in obj_rows:
            for c in obj_cols:
                out[r, c] = mark
    else:
        for r, c in painted:
            out[r, c] = mark

    return out
